SourceCode.Declaration:
/// <summary>
/// Data contract class for the cover note report
/// </summary>
[DataContract]
class METCoverNoteContract
{
    WHSShipmentId shipmentID;

}

Method.Source:
/// <summary>
/// Parm method for the shipment number
/// </summary>
/// <param name = "_shipmentId">the shipment number</param>
/// <returns>the shipment number</returns>
[
    DataMemberAttribute('WHSShipmentId'),
    SysOperationLabelAttribute('Shipment ID')
]
public WHSShipmentId parmShipmentId(WHSShipmentId _shipmentID = shipmentID)
{
    shipmentID = _shipmentId;
    return shipmentID;
}
